167	impl Manifest for PackageJson {
168	    fn path(&self) -> &Path {
169	        &self.path
170	    }
171	
172	    fn ecosystem(&self) -> Ecosystem {
173	        Ecosystem::Npm
174	    }
175	
176	    fn is_publishable(&self) -> bool {
177	        if self.doc.get("name").is_none() {
178	            return false;
179	        }
180	        if let Some(b) = self.doc.get("private").and_then(|p| p.as_bool()) {
181	            if b {
182	                return false;
183	            }
184	        }
185	        true
186	    }
187	
188	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
189	        if !self.is_publishable() {
190	            return vec![callisto_model::PublishTarget::None];
191	        }
192	        // Read `publishConfig.registry` from package.json, the standard npm
193	        // mechanism for targeting a private registry. When set, `npm publish`
194	        // must receive `--registry <url>`; when absent, the public registry is
195	        // used (npm's built-in default).
196	        let publish_config = self.doc.get("publishConfig");
197	        let registry = publish_config
198	            .and_then(|pc| pc.get("registry"))
199	            .and_then(|r| r.as_str())
200	            .map(|s| s.to_string());
201	        // Read `publishConfig.access` to propagate the operator's explicit
202	        // access intent. npm's `--access` CLI flag overrides publishConfig.access,
203	        // so callisto must read it here and honour it in plan_publish rather than
204	        // blindly passing `--access public` for all scoped packages.
205	        let restricted = publish_config
206	            .and_then(|pc| pc.get("access"))
207	            .and_then(|a| a.as_str())
208	            == Some("restricted");
209	        vec![callisto_model::PublishTarget::Npm {
210	            registry,
211	            restricted,
212	        }]
213	    }
214	
215	    fn role(&self) -> ManifestRole {
216	        self.role.clone()
217	    }
218	
219	    fn package_name(&self) -> Result<String, ManifestError> {
220	        let name = self
221	            .doc
222	            .get("name")
223	            .and_then(|n| n.as_str())
224	            .ok_or_else(|| ManifestError::MissingField {
225	                path: self.path.clone(),
226	                field: "name",
227	            })?;
228	        Ok(name.to_string())
229	    }
230	
231	    fn current_version(&self) -> Result<Version, ManifestError> {
232	        let raw = self
233	            .doc
234	            .get("version")
235	            .and_then(|v| v.as_str())
236	            .ok_or_else(|| ManifestError::MissingField {
237	                path: self.path.clone(),
238	                field: "version",
239	            })?;
240	
241	        Version::parse(raw, VersionGrammar::SemVer).map_err(|source| {
242	            ManifestError::InvalidVersion {
243	                path: self.path.clone(),
244	                raw: raw.to_string(),
245	                source,
246	            }
247	        })
248	    }
249	
250	    fn write_version(&mut self, v: &Version, permit: &ApplyPermit) -> Result<(), ManifestError> {
251	        self.doc
252	            .insert("version".to_string(), Value::String(v.render().to_string()));
253	        self.persist(permit)
254	    }
255	
256	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
257	        let mut entries = Vec::new();
258	
259	        for (section_name, kind) in [
260	            ("dependencies", DepKind::Runtime),
261	            ("devDependencies", DepKind::Dev),
262	            ("peerDependencies", DepKind::Peer),
263	            ("optionalDependencies", DepKind::Optional),
264	        ] {
265	            if let Some(obj) = self.doc.get(section_name).and_then(|v| v.as_object()) {
266	                for (name, val) in obj {
267	                    if let Some(v_str) = val.as_str() {
268	                        let spec = parse_npm_spec_str(v_str, self.npm_workspace_kind);
269	                        entries.push(DependencyEntry {
270	                            name: name.clone(),
271	                            kind,
272	                            spec,
273	                            inherited: false,
274	                        });
275	                    }
276	                }
277	            }
278	        }
279	
280	        Box::new(entries.into_iter())
281	    }
282	
283	    fn update_dependency_spec(
284	        &mut self,
285	        name: &str,
286	        kind: DepKind,
287	        new: DepSpec,
288	        permit: &ApplyPermit,
289	    ) -> Result<(), ManifestError> {
290	        if kind == DepKind::Build {
291	            return Err(ManifestError::DependencyNotFound {
292	                path: self.path.clone(),
293	                name: name.to_string(),
294	                kind,
295	            });
296	        }
297	
298	        let section_name = match kind {
299	            DepKind::Runtime => "dependencies",
300	            DepKind::Dev => "devDependencies",
301	            DepKind::Peer => "peerDependencies",
302	            DepKind::Optional => "optionalDependencies",
303	            DepKind::Build => unreachable!(),
304	        };
305	
306	        // Validate that the target dependency actually exists in the primary
307	        // section *before* mutating anything. This guarantees that a failed
308	        // update (dependency not found) leaves self.doc byte-for-byte
309	        // unchanged, including the overrides/resolutions tables below.
310	        let updated_in_section = self
311	            .doc
312	            .get(section_name)
313	            .and_then(|v| v.as_object())
314	            .is_some_and(|section| section.contains_key(name));
315	
316	        if !updated_in_section {
317	            return Err(ManifestError::DependencyNotFound {
318	                path: self.path.clone(),
319	                name: name.to_string(),
320	                kind,
321	            });
322	        }
323	
324	        if let Some(section) = self
325	            .doc
326	            .get_mut(section_name)
327	            .and_then(|v| v.as_object_mut())
328	        {
329	            section.insert(name.to_string(), Value::String(new.render()));
330	        }
331	
332	        for extra in ["overrides", "resolutions"] {
333	            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut()) {
334	                if tbl.get(name).is_some_and(|v| v.is_string()) {
335	                    tbl.insert(name.to_string(), Value::String(new.render()));
336	                }
337	            }
338	        }
339	
340	        self.persist(permit)
341	    }
342	
343	    fn update_optional_dependencies(
344	        &mut self,
345	        updates: &[(String, Version)],
346	        permit: &ApplyPermit,
347	    ) -> Result<(), ManifestError> {
348	        let section = self
349	            .doc
350	            .entry("optionalDependencies".to_string())
351	            .or_insert_with(|| Value::Object(Map::new()))
352	            .as_object_mut()
353	            .ok_or_else(|| ManifestError::FormattingNotPreserved {
354	                path: self.path.clone(),
355	                message: "optionalDependencies is not an object".to_string(),
356	            })?;
357	
358	        for (name, ver) in updates {
359	            section.insert(name.clone(), Value::String(ver.render().to_string()));
360	        }
361	
362	        self.persist(permit)
363	    }
364	}
