366	fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
367	    if let Some(rest) = s.strip_prefix("workspace:") {
368	        if let Some(kind) = ws_kind {
369	            return DepSpec::Workspace(kind);
370	        }
371	        return DepSpec::Opaque(format!("workspace:{rest}"));
372	    }
373	    if let Some(rest) = s.strip_prefix("catalog:") {
374	        let name = if rest.is_empty() {
375	            None
376	        } else {
377	            Some(rest.to_string())
378	        };
379	        return DepSpec::Catalog(name);
380	    }
381	
382	    if crate::common::is_bare_semver(s) {
383	        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
384	            return DepSpec::Exact(v);
385	        }
386	    }
387	
388	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
389	        return DepSpec::Range(req, s.to_string());
390	    }
391	
392	    DepSpec::Opaque(s.to_string())
393	}
394	
395	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
396	    match spec {
397	        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
398	        DepSpec::Range(_, original) => {
399	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
400	            if rest.contains(' ')
401	                || rest.contains('-')
402	                || rest.contains('|')
403	                || rest.contains(['x', 'X', '*'])
404	            {
405	                return None;
406	            }
407	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
408	            let req = VersionReq::parse(&rendered, Ecosystem::Npm).ok()?;
409	            Some(DepSpec::Range(req, rendered))
410	        }
411	        _ => None,
412	    }
413	}
414	
415	fn render_at_precision(target: &Version, original_clause: &str) -> String {
416	    let parts: Vec<&str> = original_clause.split('.').collect();
417	    let maj = target.major().unwrap_or(0);
418	    let min = target.minor().unwrap_or(0);
419	    let pat = target.patch().unwrap_or(0);
420	
421	    match parts.len() {
422	        1 => format!("{maj}"),
423	        2 => format!("{maj}.{min}"),
424	        _ => format!("{maj}.{min}.{pat}"),
425	    }
426	}
